{"type":"ReadFile","FileContent":{"content":"170→ * Copy hidden test files into the run dir, overwriting whatever is there.
 *
 * Runs after the agent has exited, so nothing it did can have read or edited
 * these files; a `to` path that escapes the run dir is refused rather than
 * written, because a task file is data and should never reach outside it.
 */
export function installHidden(files: ReadonlyArray<{ from: string; to: string }>, tasksDir: string, dir: string): string[] {
  const root = path.resolve(dir);
  return files.map(({ from, to }) => {
    const dest = path.resolve(root, to);
180→    if (!dest.startsWith(root + path.sep)) throw new Error(`hidden test path escapes the run dir: ${to}`);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.copyFileSync(path.resolve(tasksDir, from), dest);
    return to;
  });
}

function runVitest(spec: string, dir: string): VitestOutcome {
  const res = spawnSync("pnpm", ["exec", "vitest", "run", spec], {
    cwd: dir,
190→    encoding: "utf8",
    timeout: 10 * 60_000,
    maxBuffer: 32 * 1024 * 1024,
  });
  if (res.error) {
    return { ran: false, passed: null, exitCode: null, spec, outputTail: null, error: String(res.error) };
  }
  const output = `${res.stdout ?? ""}\n${res.stderr ?? ""}`;
  return {
    ran: true,
200→    passed: res.status === 0,
    exitCode: res.status,
    spec,
    outputTail: output.trim().split("\n").slice(-40).join("\n"),
  };
}

/**
 * sha256 over an index directory's sorted relative file list and contents.
 *
210→ * The palace is gitignored and rebuilt rather than committed, so this is the
 * only handle on "which index did these 65 runs actually query". Relative paths
 * go into the digest, not absolute ones, so the hash is a property of the index
 * and not of where the checkout happens to live.
 */
function hashDir(dir: string): { hash: string; files: number; bytes: number } {
  const rels: string[] = [];
  const walk = (rel: string): void => {
    for (const entry of fs.readdirSync(path.join(dir, rel), { withFileTypes: true })) {
      const child = rel ? path.join(rel, entry.name) : entry.name;
220→      if (entry.isDirectory()) walk(child);
      else if (entry.isFile()) rels.push(child);
    }
  };
  walk("");
  rels.sort();
  const outer = crypto.createHash("sha256");
  let bytes = 0;
  for (const rel of rels) {
    const buf = fs.readFileSync(path.join(dir, rel));
230→    bytes += buf.length;
    outer.update(`${crypto.createHash("sha256").update(buf).digest("hex")}  ${rel}\n`);
  }
  return { hash: outer.digest("hex"), files: rels.length, bytes };
}

