/**
 * Read-only lock for a workspace whose subscription is not in good standing.
 *
 * `lockReasonFor` is the pure rule evaluated against the subscription row.
 * Write paths call `assertWorkspaceWritable` after the permission check.
 */
import { parseIso } from "@/lib/date";
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** A member write was refused because the workspace is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only (${reason})`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * Why a workspace cannot be written, or `null` when it is writable.
 *
 * `active` and a missing subscription row are writable. A trial locks at its
 * period end. A cancellation locks at `cancelAt` — a date still in the future
 * keeps the workspace writable, and a missing date counts as canceled now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return reached(subscription.cancelAt, now) ? "canceled" : null;
    default: {
      const unreachable: never = subscription.status;
      return unreachable;
    }
  }
}

/** True once `instant` has been reached (`now` is at or after it). */
function reached(instant: Subscription["currentPeriodEnd"], now: Date): boolean {
  return now.getTime() >= parseIso(instant).getTime();
}

